window.ScripturaLexicons.BDAG_PART_0166 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theiotes-bdag\" data-source=\"BDAG\" data-search=\"θειότης, ητος, ἡ substantivo feminino divindade; natureza divina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θειότης, ητος, ἡ</td><td>substantivo feminino</td><td>divindade; natureza divina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theiodes-bdag\" data-source=\"BDAG\" data-search=\"θειώδης, ες adjetivo de dois gêneros sulfuroso; que contém enxofre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θειώδης, ες</td><td>adjetivo de dois gêneros</td><td>sulfuroso; que contém enxofre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thekla-bdag\" data-source=\"BDAG\" data-search=\"Θέκλα, ης, ἡ nome próprio feminino Tecla BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θέκλα, ης, ἡ</td><td>nome próprio feminino</td><td>Tecla</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thelema-bdag\" data-source=\"BDAG\" data-search=\"θέλημα, ατος, τό substantivo neutro aquilo que se quer; propósito; vontade; ato de querer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέλημα, ατος, τό</td><td>substantivo neutro</td><td>aquilo que se quer; propósito; vontade; ato de querer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thelesis-bdag\" data-source=\"BDAG\" data-search=\"θέλησις, εως, ἡ substantivo feminino ato de querer; vontade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέλησις, εως, ἡ</td><td>substantivo feminino</td><td>ato de querer; vontade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thelo-bdag\" data-source=\"BDAG\" data-search=\"θέλω verbo querer; desejar; resolver; preferir; apreciar; considerar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέλω</td><td>verbo</td><td>querer; desejar; resolver; preferir; apreciar; considerar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thema-bdag\" data-source=\"BDAG\" data-search=\"θέμα, ατος, τό substantivo neutro prêmio; recompensa oferecida em dinheiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θέμα, ατος, τό</td><td>substantivo neutro</td><td>prêmio; recompensa oferecida em dinheiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-themelion-bdag\" data-source=\"BDAG\" data-search=\"θεμέλιον, ου, τό substantivo neutro fundação; alicerce; base BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεμέλιον, ου, τό</td><td>substantivo neutro</td><td>fundação; alicerce; base</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-themelios-bdag\" data-source=\"BDAG\" data-search=\"θεμέλιος, ου, ὁ substantivo masculino fundamento; alicerce; base; reserva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεμέλιος, ου, ὁ</td><td>substantivo masculino</td><td>fundamento; alicerce; base; reserva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-themelioo-bdag\" data-source=\"BDAG\" data-search=\"θεμελιόω verbo lançar alicerces; fundar; estabelecer; fortalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεμελιόω</td><td>verbo</td><td>lançar alicerces; fundar; estabelecer; fortalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-themitos-bdag\" data-source=\"BDAG\" data-search=\"θεμιτός, ή, όν adjetivo permitido; lícito; apropriado; justo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεμιτός, ή, όν</td><td>adjetivo</td><td>permitido; lícito; apropriado; justo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theodidaktos-bdag\" data-source=\"BDAG\" data-search=\"θεοδίδακτος, ον adjetivo de dois gêneros ensinado por Deus; instruído por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοδίδακτος, ον</td><td>adjetivo de dois gêneros</td><td>ensinado por Deus; instruído por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theodromos-bdag\" data-source=\"BDAG\" data-search=\"θεοδρόμος, ου, ὁ substantivo masculino corredor de Deus; mensageiro que corre por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοδρόμος, ου, ὁ</td><td>substantivo masculino</td><td>corredor de Deus; mensageiro que corre por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theologos-bdag\" data-source=\"BDAG\" data-search=\"θεολόγος, ου, ὁ substantivo masculino aquele que fala de Deus; arauto de Deus; teólogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεολόγος, ου, ὁ</td><td>substantivo masculino</td><td>aquele que fala de Deus; arauto de Deus; teólogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theomakaristos-bdag\" data-source=\"BDAG\" data-search=\"θεομακάριστος, ον adjetivo de dois gêneros abençoado por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεομακάριστος, ον</td><td>adjetivo de dois gêneros</td><td>abençoado por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theomakarites-bdag\" data-source=\"BDAG\" data-search=\"θεομακαρίτης, ου, ὁ substantivo masculino empregado como adjetivo divinamente abençoado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεομακαρίτης, ου, ὁ</td><td>substantivo masculino empregado como adjetivo</td><td>divinamente abençoado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theomacheo-bdag\" data-source=\"BDAG\" data-search=\"θεομαχέω verbo combater Deus; opor-se a Deus e às suas obras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεομαχέω</td><td>verbo</td><td>combater Deus; opor-se a Deus e às suas obras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theomachos-bdag\" data-source=\"BDAG\" data-search=\"θεομάχος, ον adjetivo de dois gêneros que combate contra Deus; adversário de Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεομάχος, ον</td><td>adjetivo de dois gêneros</td><td>que combate contra Deus; adversário de Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theonoe-bdag\" data-source=\"BDAG\" data-search=\"Θεονόη, ης, ἡ nome próprio feminino Teónoe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θεονόη, ης, ἡ</td><td>nome próprio feminino</td><td>Teónoe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-theopneustos-bdag\" data-source=\"BDAG\" data-search=\"θεόπνευστος, ον adjetivo de dois gêneros inspirado por Deus; soprado por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεόπνευστος, ον</td><td>adjetivo de dois gêneros</td><td>inspirado por Deus; soprado por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-theiotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θειότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">θεῖος</span>; sobre a manifestação de qualidades próprias de uma divindade, e não simples tautologia: Plutarco, Mor. 398a; 665a; Luciano, Calumn. 17; Herm. Wr. 9, 1c; SIG 867, 31: Ártemis tornou Éfeso célebre <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">θειότητος</span>, «pelas manifestações de seu próprio poder», cf. linha 35; POxy 1381, 165: <span class=\"greek\">πληρωθεὶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σῆς</span> <span class=\"greek\">θειότητος</span>, de Imutes-Asclépio e das curas; PGM 7, 691; Sb 18:9; EpArist 95; ApcSed 14:8; 15:2; Fílon, Op. M. 172, variante; Justino, D. 3:5. De pessoas próximas da divindade: Heráclito, Alleg. Hom. 76, p. 102, 4, de Homero; Josefo, Ant. 10, 268, de Daniel; inscrições e papiros, de príncipes e imperadores, por exemplo Augusto, SEG XXVI 1392, 31 [18–19 d.C.]. Do anúncio cristão: <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">λόγου</span>, «o caráter divino da nossa mensagem», Teófilo de Antioquia 3, 29 [p. 264, 16].) <strong>Qualidade ou características próprias da divindade: divindade, natureza divina</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:20</a>. — H. Nash, «<span class=\"greek\">θειότης</span> – <span class=\"greek\">θεότης</span>, Ro 1:20, Col 2:9», JBL 18, 1899, 1–34; New Docs 3, 68; DELG, s.v. <span class=\"greek\">θεός</span>; Lampe; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-theiodes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θειώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">θεῖος</span> + -<span class=\"greek\">ώδης</span>; Diodoro Sículo 2, 12, 2; Estrabão 1, 3, 18; Herão de Alexandria I, p. 12, 8; III, p. 214, 7; Areteu 170, 12; Galeno, CMG V 4, 2, p. 107, 33; 186, 5 e outros.) <strong>Sulfuroso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:17</a>.</p></section></article>\n<article id=\"entry-thekla-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θέκλα, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Até o momento documentado somente como nome cristão: CIG 8683; 9138; 9139; PBodl não catalogado, JEA 23, 1937, 10s., genitivo <span class=\"greek\">Θέκλας</span>; AcPlTh [Aa I 235–72], passim.) <strong>Tecla</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:11</a>, glosa; AcPl Ox 6 (duas ocorrências).</p></section></article>\n<article id=\"entry-thelema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέλημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes seguintes; Antífon Sofista 58; Aristóteles, De Plant. 1, 1, p. 815b, 21; Eneias Tático 2, 8; 18, 19; POxy 924, 8 [século IV d.C.]; LXX; PsSol 7:3; OdeSol 11:21; TestSol; Test12Patr; JosAs; ParJer 1:7; ApcEsdr 4:24, p. 28, 2 Tdf.; ApcSed; Justino; Taciano; Melitão, P. 76, 552.)</p><p class=\"entry-text\">① <strong>Aquilo que alguém deseja que aconteça, em sentido objetivo; aquilo que é querido.</strong></p><p class=\"entry-text\">ⓐ Em geral: <span class=\"greek\">ἐὰν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ᾖ</span>, «se for a vontade dele [de Deus ou Cristo]», IEph 20:1; IRo 1:1 (o emprego absoluto como vontade de Deus também em ISm 11:1; IPol 8:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:18</a>). <span class=\"greek\">γενηθήτω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημά</span> <span class=\"greek\">σου</span>, «seja feita a tua vontade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:10</a>; 26:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:2</a>, variante; D 8:2; <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">γενέσθω</span>, «seja feita a vontade de Deus», MPol 7:1. <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πέμψαντός</span> <span class=\"greek\">με</span>, «esta é a vontade daquele que me enviou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:39s</a>.; <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σὸν</span> <span class=\"greek\">γινέσθω</span>, «não a minha vontade, mas a tua», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:42</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:10</a> (única ocorrência neotestamentária dessa palavra com <span class=\"greek\">ἐν</span>, cf. AcPlCor 2:26). <span class=\"greek\">οὕτως</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἵνα</span>, «assim não é vontade do Pai que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:14</a> (<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">θ</span>. como Ml 1:10; Ec 5:3; 12:1).</p><p class=\"entry-text\">ⓑ <strong>Aquilo que alguém deseja realizar por sua própria atividade</strong>, porque pretende executar o que quis: <span class=\"greek\">οὐ</span> <span class=\"greek\">ζητῶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμόν</span>, «não procuro realizar a minha vontade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:30a</a>; 6:38. <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">αὐτοῦ</span>, «o propósito secreto da vontade dele», isto é, a realização do plano salvífico divino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:9</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">θ</span>., <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔλθῃ</span>, «não estava disposto a vir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:12</a> (também pode pertencer ao uso absoluto de ①ⓐ).</p><p class=\"entry-text\">ⓒ <strong>Aquilo que se quer realizar mediante a atividade de outros, a quem se atribui uma tarefa</strong>.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De pessoas: <span class=\"greek\">ὁ</span> <span class=\"greek\">δοῦλος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">γνοὺς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">αὐτοῦ</span>, «o servo que conhece o que seu senhor quer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:47</a> (parábola); <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, «a vontade do pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Do diabo: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">θ</span>., «para fazer a vontade dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:26</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Sobretudo de Deus ou Cristo: <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (Herm. Wr. 5, 7; 13, 2; Fílon, Leg. All. 3, 197; TestIss 4:3; TestNapht 3:1; Justino, A I, 63, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:3</a>; 5:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:15</a>; 4:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:30b</a>; 1Cl 40:3; 56:2. <span class=\"greek\">θελήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κελεύοντος</span> <span class=\"greek\">λόγου</span>, «pela vontade da Palavra que ordena», Dg 11:8. <span class=\"greek\">γινώσκειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span>, «conhecer a vontade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:14</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπίγνωσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">αὐτοῦ</span>, «o pleno conhecimento da vontade dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:9</a>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>., «fazer a vontade» (1Esd 9:9; 4Mc 18:16; JosAs 12:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:21</a>; 12:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:34</a>; 6:38b; 7:17; 9:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:7</a>, 9 (Sl 39:9), 36; 13:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:17</a>; 2Cl 5:1; 6:7; 8:4; 9:11; 10:1; 14:1; Pol 2:2. Também <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θελήματα</span>, «cumprir os desejos» (Sl 102:21; Is 44:28; 2Mc 1:3), GEb 121, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:35</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:22</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">λειποτακτεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">αὐτοῦ</span>, «não desertar da vontade dele», 1Cl 21:4. <span class=\"greek\">προσέλθωμεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">αὐτοῦ</span>, «prestemos atenção à vontade dele», 1Cl 33:8; <span class=\"greek\">ὑποτασσώμεθα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">αὐτοῦ</span>, «sujeitemo-nos à vontade dele», 1Cl 34:5 (oposto a <span class=\"greek\">ἀντιτασσόμενος</span>, 36:6; <span class=\"greek\">ἐναντιουμένους</span>, 61:1); <span class=\"greek\">εἶξαι</span> … <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «ceder à vontade de Deus», 1Cl 56:1.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θελήματα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σαρκός</span>, «cumprir os desejos da carne», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:3</a>.</p><p class=\"entry-text\">② <strong>Ato de querer ou desejar, sentido subjetivo: vontade.</strong></p><p class=\"entry-text\">ⓐ Da vontade humana (Sl 1:2): <span class=\"greek\">θελήματι</span> <span class=\"greek\">ἀνθρώπου</span>, «por ato da vontade humana», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:21</a>. <span class=\"greek\">ἐὰν</span> … <span class=\"greek\">ἐπιδῶμεν</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θελήμασιν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, «se inadvertidamente nos deixarmos governar pelas vontades humanas», 1Cl 14:2. <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἰδίου</span> <span class=\"greek\">θ</span>., «ter domínio sobre o próprio desejo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:37</a>; aqui alguns lhe atribuem conotação de desejo sexual, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:13</a> (<span class=\"greek\">θ</span>. <span class=\"greek\">σαρκός</span>, <span class=\"greek\">θ</span>. <span class=\"greek\">ἀνδρός</span>; cf. PGM 4, 1430, 1521, 1533). Da vontade de uma multidão reunida, dirigida à morte de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:25</a>.</p><p class=\"entry-text\">ⓑ Habitualmente da vontade de Deus ou Cristo: <span class=\"greek\">ἡ</span> <span class=\"greek\">βουλὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «o desígnio da vontade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:11</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐδοκία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «o beneplácito da vontade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:5</a> (cf. CD 3, 15). <span class=\"greek\">εἰ</span> <span class=\"greek\">θέλοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «se a vontade de Deus assim decretar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:17</a> (cf. Justino, D. 119, 1, <span class=\"greek\">θελήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήσαντος</span>). <span class=\"greek\">θελήματι</span> <span class=\"greek\">θεοῦ</span>, «pela vontade de Deus», ITr 1:1; Pol 1:3. <span class=\"greek\">διὰ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:1</a>; 8:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:1</a>; 1Cl 32:3s.; <span class=\"greek\">Χριστοῦ</span>, AcPl Ha 5, 35. Ainda <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:11</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θελήματι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:10</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">θεοῦ</span>, 1Cl 49:6; AcPl Ha 7, 13; AcPlCor 2:26; cf. 1Cl, inscrição; IEph, inscrição; <span class=\"greek\">ἐκ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">θεοῦ</span> (cf. Sl 27:7), 1Cl 42:2; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>., «conforme a vontade [do senhor]», Hs 9, 5, 2; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. (1Esd 8:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:19</a>; IPhld, inscrição; ISm 1:1; 1Cl 20:4; Hm 12, 6, 2; MPol 2:1 (Justino, D. 85, 4). — DELG, s.v. <span class=\"greek\">ἐθέλω</span>; M-M; TW.</p><p class=\"entry-text\">Nota lexical: <span class=\"greek\">θέλημα</span> aparece também como substantivo absoluto <span class=\"greek\">θ</span>. no contexto da vontade divina (cf. ISm 11:1; IPol 8:1).</p></section></article>\n<article id=\"entry-thelesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέλησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver verbetes anterior e seguinte; para Pólux 5, 47, expressão <span class=\"greek\">ἰδιωτικόν</span>, «vulgar»; cf. Frínico, p. 353 Lob. Também nos estoicos III 41; Filodemo, Rhet. II 297 Sudh.; PGM 4, 1429, <span class=\"greek\">θέλησις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θελημάτων</span>; Ez 18:23; 2Cr 15:15; Pv 8:35; TestSol D; AcThom 169 [Aa II/2, 284, 6]; Justino, D. 60, 2; 61, 1; plural dórico <span class=\"greek\">θελήσιες</span>, «desejos», Melissa, Epist. ad Char., p. 62 Orell.) <strong>Ato de querer: vontade</strong>, de Deus (Herm. Wr. 4, 1a; 10, 2; Jâmblico, De Myst. 2, 11, p. 97, 15 Parthey, <span class=\"greek\">ἡ</span> <span class=\"greek\">θεία</span> <span class=\"greek\">θ</span>.): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">θ</span>., «segundo a vontade dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>; <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">θ</span>., «pela vontade dele» (Tb 12:18; 2Mc 12:16), 2Cl 1:6. — DELG, s.v. <span class=\"greek\">ἐθέλω</span>; TW.</p></section></article>\n<article id=\"entry-thelo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes precedentes. Sobre a relação com o ático <span class=\"greek\">ἐθέλω</span>, ausente do NT, da LXX e de En, TestSol, TestAbr, TestJob, Test12Patr, GrBar, JosAs, ParJer, ApcEsdr, ApcMos e AscIs, ver Kühner–Blass I 187s.; II 408s.; B-D-F §101, p. 45; Mlt-H. 88, 189; Rob. 205s. <span class=\"greek\">θέλω</span> ocorre desde 250 a.C. em inscrições áticas [Meisterhans³–Schw. 178; Threatte II 637s.] e predomina nos papiros [Mayser I²/2, 1938, 119], na LXX e nos autores mencionados; Josefo, Ant. 18, 144; C. Ap. 2, 192; apologistas, exceto Melitão [mas ver <span class=\"greek\">ἐθέλω</span>].) Imperfeito <span class=\"greek\">ἤθελον</span>; futuro <span class=\"greek\">θελήσω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:5</a>, variante; primeiro aoristo <span class=\"greek\">ἠθέλησα</span> (<span class=\"greek\">ἤθελα</span>, TestAbr A 5, p. 82, 2 [Stone p. 12]; sobre o aumento, B-D-F §66, 3; Mlt-H. 188); perfeito segunda pessoa singular <span class=\"greek\">τεθέληκας</span>, Sl 40:11; subjuntivo de primeiro aoristo passivo <span class=\"greek\">θεληθῶ</span>, IRo 8:1.</p><p class=\"entry-text\">① <strong>Ter desejo de alguma coisa: querer possuir, desejar, querer</strong>, com acusativo <span class=\"greek\">τι</span>, «algo» (sobre distinção frente a <span class=\"greek\">βούλομαι</span>, ver esse verbete; Diógenes, o Cínico, Fgm. 2; Trágicos Gregos, p. 809 Nauck²; Sótades [280 a.C., não o comediógrafo] em Estobeu 3, 1, 66, III, p. 27, 5 H.; <span class=\"greek\">πάντα</span> <span class=\"greek\">θέλων</span>, Teócrito 14, 11; <span class=\"greek\">πάντα</span>, <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">θελήσωμεν</span>, <span class=\"greek\">ποιήσωμεν</span>, En 97:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:36</a> (D. Daube, <em>A Prayer Pattern in Judaism</em>, TU 73, 1959, 539–45); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:12</a>. Com infinitivo presente: <span class=\"greek\">τί</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">θέλετε</span> <span class=\"greek\">ἀκούειν</span>;, «por que quereis ouvir [isso] de novo?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:27a</a>; <span class=\"greek\">εἰ</span> <span class=\"greek\">θέλεις</span> <span class=\"greek\">τέλειος</span> <span class=\"greek\">εἶναι</span>, «se queres ser perfeito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:21</a> (Luciano, Dial. Deor. 2, 2, <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐθέλεις</span> <span class=\"greek\">ἐπέραστος</span> <span class=\"greek\">εἶναι</span>); <span class=\"greek\">ἤθελεν</span> <span class=\"greek\">ἀπολογεῖσθαι</span>, «desejava apresentar defesa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:33</a>; <span class=\"greek\">ἤθελον</span> <span class=\"greek\">παρεῖναι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἄρτι</span>, «quisera estar convosco agora», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:20</a>. <span class=\"greek\">ἤθελον</span>, «gostaria», com infinitivo aoristo (Epicteto 1, 29, 38; PLond III 897, 20, p. 207 [84 d.C.]), Hv 3, 8, 6; 3, 11, 4 (B-D-F §359, 2; Rob. 923). <span class=\"greek\">θέλω</span> com infinitivo aoristo também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:40</a>; 12:38; 16:25; 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:20</a>; 23:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:21</a> (Diógenes Laércio 6, 34, <span class=\"greek\">ξένων</span> <span class=\"greek\">δέ</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">θεάσασθαι</span> <span class=\"greek\">θελόντων</span> <span class=\"greek\">Δημοσθένην</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:9b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:32</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:20</a> (cf. Sêneca, Ep. 47, 10, <em>vis tu cogitare</em>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:10</a>; B 7:11; Ar. 13:5; Justino, D. 8:4; Taciano 19, 2; Atanásio 32, 1. Absoluto, com infinitivo subentendido no contexto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a> (<span class=\"greek\">ποιῆσαι</span>); 27:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:18</a>. Seguido de acusativo e infinitivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:62</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:22s</a>.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:7</a>, 32; 14:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:13</a> (Justino, D. 6, 2; Taciano 19, 3). Negativo <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλω</span> (outros modos usam <span class=\"greek\">μή</span>): <strong>não quero, não estou disposto</strong>, com acusativo e infinitivo aoristo (Justino, D. 28, 4, <span class=\"greek\">περιτομήν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:14</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:20</a>; IRo 2:1. <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλω</span> (<span class=\"greek\">θέλομεν</span>) <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀγνοεῖν</span>, «não quero que ignoreis», isto é, «quero que saibais» (BGU 27, 5; PGiss 11, 4 [118 d.C.], <span class=\"greek\">γινώσκειν</span> <span class=\"greek\">σε</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">ὅτι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:13</a>; 11:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:1</a>; 12:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:13</a>. Seguido de <span class=\"greek\">ἵνα</span> (Epicteto 1, 18, 14; 2, 7, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:25</a>; 9:30; 10:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17:24</a> (sobre a regra áurea em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:31</a> [com infinitivo <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">γίνεσθαι</span> em Ar. 15, 5], L. Philippidis, <em>D. Goldene Regel</em>, 1929, e <em>Forschungsberichte</em>, 1933; G. King, JR 8, 1928, 268–79; A. Dihle, 1962; Betz, SM, ad loc.). Com subjuntivo aoristo deliberativo (Kühner–Gerth I 221s.; B-D-F §366, 3; 465, 2; Rob. 935; Epicteto 3, 2, 14, <span class=\"greek\">θέλεις</span> <span class=\"greek\">σοι</span> <span class=\"greek\">εἴπω</span>;, «queres que te diga?»; Mitt-Wilck. I/2, 14 III, 6, <span class=\"greek\">καὶ</span> <span class=\"greek\">σοὶ</span> [= <span class=\"greek\">σὺ</span>] <span class=\"greek\">λέγε</span> <span class=\"greek\">τίνος</span> <span class=\"greek\">θέλεις</span> <span class=\"greek\">κατηγορήσω</span>): <span class=\"greek\">θέλεις</span> <span class=\"greek\">συλλέξωμεν</span> <span class=\"greek\">αὐτά</span>;, «queres que os recolhamos?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:28</a>; <span class=\"greek\">θέλις</span> <span class=\"greek\">χαλκέα</span> <span class=\"greek\">ἄγωμεν</span>;, «queres que tragam um ferreiro?», AcPl Ha 3, 5; <span class=\"greek\">τί</span> <span class=\"greek\">θέλετε</span> <span class=\"greek\">ποιήσω</span> <span class=\"greek\">ὑμῖν</span>;, «que quereis que eu vos faça?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:32</a> (cf. Plauto, Merc. 1, 2, 49, linha 159); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:17</a>; 27:17, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:36</a> (C. Turner, JTS 28, 1927, 357; A. Higgins, ET 52, 1941, 317s.), 51; 14:12; 15:9, 12, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:54</a>; 18:41; 22:9. Com <span class=\"greek\">ἤ</span>: <strong>preferir uma coisa a outra</strong> (Trífon de Alexandria [século I a.C.], Fgm. 23 [A. von Velsen 1853] = Gramm. Gr. II/2, p. 43, 10, <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">ἤπερ</span> <span class=\"greek\">ἑστάναι</span>; Epicteto 3, 22, 53; BGU 846, 15 [século II d.C.], <span class=\"greek\">θέλω</span> <span class=\"greek\">πηρὸς</span> <span class=\"greek\">γενέσθαι</span>, <span class=\"greek\">ἢ</span> <span class=\"greek\">γνῶναι</span>, <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἀνθρώπῳ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὀφείλω</span> <span class=\"greek\">ὀβολόν</span>; 2Mc 14:42; Justino, A I, 15, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:19</a>. Com <span class=\"greek\">εἰ</span> (Is 9:4s.; Eclo 23:14): <span class=\"greek\">τί</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">ἀνήφθη</span>, «como desejo que já estivesse aceso!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:49</a>.</p><p class=\"entry-text\">② <strong>Ter algo em mente como propósito; decidir, querer, estar disposto a fazer</strong> <span class=\"greek\">τι</span>, «algo» (Platão, Apol. 41a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:15s</a>., 19s. (Epicteto 2, 26, 1, <span class=\"greek\">ὃ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιεῖ</span>, «não faz o que decide»; cf. 2, 26, 2, 4, e <span class=\"greek\">ποιέω</span> 2e; Ar. 9, 1; Justino, D. 2, 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:17</a>. Com infinitivo aoristo (Jz 20:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:14</a>; 20:14; 23:37; 26:15; <span class=\"greek\">ἤθελεν</span> <span class=\"greek\">παρελθεῖν</span> <span class=\"greek\">αὐτούς</span>, «estava prestes a passar por eles», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:48</a> (C. Turner, JTS 28, 1927, 356); <span class=\"greek\">Ἡρῴδης</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἀποκτεῖναι</span>, «Herodes quer matar-te», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:31</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:43</a>; <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἠθελήσατε</span> <span class=\"greek\">ἀγαλλιασθῆναι</span>, «quisestes alegrar-vos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:35</a>; 6:21; 7:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:9a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:5</a>. Com infinitivo presente (2Esd 11:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.67\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:67</a>; 7:17; 8:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:13</a>; 17:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:21</a>; 2Cl 6:1; B 4:9. Absoluto, com infinitivo subentendido: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:2</a> (Epicteto 3, 10, 15, <span class=\"greek\">ἐὰν</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">θέλῃς</span>, <span class=\"greek\">κύριε</span>, <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἕξω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:13</a>; 6:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:21</a>; Rm 9:18ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:6</a>; <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">θέλετε</span>, <span class=\"greek\">κρίνατε</span>, «decidi, pois, o que quereis», AcPl Ha 1, 26. Acusativo com infinitivo, 1Cl 36:2. Substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">θέλων</span>, «aquele que quer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:16</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θέλοντος</span>, «se Deus quiser» (Josefo, Ant. 7, 373; PMich 211, 4, <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σεράπιδος</span> <span class=\"greek\">θέλοντος</span>; PAmh 131, 5; PGiss 18, 10; BGU 423, 18; 615, 4s.; Ar. 7, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:21</a>; <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">θελήσῃ</span>, «se o Senhor quiser» (Platão, Phd. 80d; Pseudo-Platão, Alcib. I 135d; Demóstenes 4, 7; 25, 2; Pseudo-Demétrio, Form. Ep. 11, 12; PPetr I 2, 3; Justino, D. 5, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:15</a>; 1Cl 21:9. <span class=\"greek\">ὅτε</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">θέλει</span>, «quando quer e como quer», 1Cl 27:5 (cf. BGU 27, 11, <span class=\"greek\">ὡς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἤθελεν</span>); <span class=\"greek\">καθὼς</span> <span class=\"greek\">ἠθέλησεν</span>, «como [Deus] quis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:18</a>; 15:38 (hino a Ísis, SEG VIII 549, 19s., <span class=\"greek\">πᾶσι</span> <span class=\"greek\">μερίζεις</span> <span class=\"greek\">οἷσι</span> <span class=\"greek\">θέλεις</span>). Cf. <span class=\"greek\">εἰ</span> <span class=\"greek\">θέλοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «se Deus assim quiser», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:17</a>, variante <span class=\"greek\">θέλει</span> (sobre oscilação entre optativo e indicativo nos manuscritos, cf. Sófocles, Ant. 1032). Negativo <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλω</span>, «não pretendo, não estou disposto» com infinitivo presente (Gn 37:35; Is 28:12; Taciano 4:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 3:10</a>; 2Cl 13:1; com infinitivo aoristo (2Km 23:16; Jr 11:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jr 38:15); 15:32; 22:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:7</a>; Dg 10:7. Absoluto, infinitivo contextual, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:4</a>; <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλω</span>, «prefiro não», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:29</a>; AcPl Ha 3, 6; 7, 3. Propósito oposto a <span class=\"greek\">ἐνεργεῖν</span>, «operar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:13</a>; <span class=\"greek\">κατεργάζεσθαι</span>, «realizar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:18</a>; <span class=\"greek\">ποιεῖν</span>, «fazer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:10</a> (Betz, <em>2Co</em>, p. 64); <span class=\"greek\">πράσσειν</span>, «praticar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:15</a>, 19.</p><p class=\"entry-text\">③ <strong>Ter prazer em, gostar de</strong>.</p><p class=\"entry-text\">ⓐ Com infinitivo: gostar de fazer algo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:38</a> (mais adiante na mesma frase com acusativo, ver ⓑ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:46</a> (com <span class=\"greek\">φιλεῖν</span>).</p><p class=\"entry-text\">ⓑ Com acusativo pessoal <span class=\"greek\">τινά</span> (Górgias: Vorsokr. 82 Fgm. 29, Gnomolog. Vatic. 166, <span class=\"greek\">τοῖς</span> <span class=\"greek\">μνηστῆρσιν</span>, <span class=\"greek\">οἳ</span> <span class=\"greek\">Πηνελόπην</span> <span class=\"greek\">θέλοντες</span>; Vi. Aesopi W 31, <span class=\"greek\">θέλω</span> <span class=\"greek\">αὐτήν</span>; Sl 40:12; Tb 13:8; ParJer 8:2, <span class=\"greek\">ὁ</span> <span class=\"greek\">θέλων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a> (Sl 21:9); IMg 3:2. Acusativo de coisa <span class=\"greek\">τὶ</span> (Epicteto 1, 4, 27; Ez 18:32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>; 12:7 (Os 6:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a>, 8 (Sl 39:7). Com <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (neutro, TestAsh 1:6, variante <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">θέλῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">καλῷ</span>; Sl 111:1; 146:10; masculino, 1Km 18:22; 2Km 15:26; 3Km 10:9), <span class=\"greek\">θέλων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταπεινοφροσύνῃ</span>, «tendo prazer na humildade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:18</a> (Agostinho, Ep. 149, 27 [MPL 33, 641s.]; A. Fridrichsen, ZNW 21, 1922, 135s.; B-D-F §148, 2; Rob. §148, 2).</p><p class=\"entry-text\">ⓒ Absoluto, <strong>sentir afeição</strong>, talvez subentendendo «por mim» (oposto a <span class=\"greek\">μισεῖν</span>), IRo 8:3.</p><p class=\"entry-text\">④ <strong>Sustentar uma opinião, insistir em algo contrário ao estado real</strong> (Pausânias 1, 4, 6, <span class=\"greek\">Ἀρκάδες</span> <span class=\"greek\">ἐθέλουσιν</span> <span class=\"greek\">εἶναι</span>; 8, 36, 2; Herodiano 5, 3, 5, <span class=\"greek\">εἰκόνα</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">ἀνέργαστον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">θέλουσιν</span>): <span class=\"greek\">λανθάνει</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">θέλοντας</span>, «ao sustentarem isso, esquecem-se», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:5</a>. Do diabo: [<span class=\"greek\">θεὸς</span>] <span class=\"greek\">θέλων</span> <span class=\"greek\">εἶναι</span>, «querendo ser [Deus]», AcPlCor 2:11. — H. Riesenfeld, <em>Zum Gebrauch von <span class=\"greek\">θέλω</span> im NT</em>, Uppsala 1, 1936, 1–8; A. Wifstrand, <em>Die griechischen Verba für wollen</em>, Eranos 40, 1942.</p><p class=\"entry-text\">⑤ <strong>Que significa isto?</strong>, <span class=\"greek\">τί</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">εἶναι</span>;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:12</a>; cf. 17:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:26</a>, códice D. — B. 1160; DELG, s.v. <span class=\"greek\">ἐθέλω</span>; EDNT; TW; Sv.</p><p class=\"entry-text\">Outros paralelos e formas da documentação para ① e ②: <span class=\"greek\">ἐὰν</span>, «se»; <span class=\"greek\">εἰ</span>, «se»; <span class=\"greek\">τὶ</span>, «algo», como objeto do querer; <span class=\"greek\">θέλω</span>, lema verbal; <span class=\"greek\">θέλοντος</span>, «daquele que quer», usado com genitivo absoluto; <span class=\"greek\">θελόντων</span>, «dos que queriam», em Diógenes Laércio 6, 34 e construções afins. A disposição de agir é explicitada por <span class=\"greek\">εἰ</span> <span class=\"greek\">θελήσομεν</span> <span class=\"greek\">ἐπεξελθεῖν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>, «se quisermos examinar a argumentação», Ar. 9, 1, e por <span class=\"greek\">θέλω</span> <span class=\"greek\">εἰπεῖν</span>, «quero falar», Justino, D. 2, 2. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:35</a>, <span class=\"greek\">ἠθελήσετε</span>, «quisestes», marca o propósito dos ouvintes. Em testemunhos relativos à vontade divina: <span class=\"greek\">ἐλπίζω</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">θελόντων</span> <span class=\"greek\">διαφεύξεσθαι</span>, «espero escapar, se os deuses quiserem», PAmh 131, 5; <span class=\"greek\">μὴ</span> <span class=\"greek\">θέλοντος</span> <span class=\"greek\">αὐτοῦ</span>, «não querendo ele», Ar. 7, 1; <span class=\"greek\">ἂν</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">θέλῃ</span>, «se Deus quiser», Demóstenes 25, 2; <span class=\"greek\">ἐὰν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">θ</span>., «se os deuses quiserem», Pseudo-Demétrio, Form. Ep. 11, 12; <span class=\"greek\">ἔστ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">θέλῃ</span>, «enquanto Deus quiser», Justino, D. 5, 3; <span class=\"greek\">πᾶσι</span> <span class=\"greek\">μερίζεις</span> <span class=\"greek\">οἷσι</span> <span class=\"greek\">θέλεις</span>, «distribuis a todos a quem queres», SEG VIII 549, 19s. A construção negativa <span class=\"greek\">ὃ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιεῖ</span>, «não faz aquilo que decide», exprime contraste entre a vontade e a ação; <span class=\"greek\">τὶ</span> e <span class=\"greek\">θ</span>. são abreviações lexicográficas recorrentes do objeto e do próprio verbo.</p><p class=\"entry-text\">Os testemunhos anotam ainda <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">μὲν</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιεῖ</span>, variante gráfica da citação de Epicteto; o contraste do planejamento inclui <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">θελόντων</span> nos papiros, e o desejo é marcado por <span class=\"greek\">θέλει</span> seguido de <span class=\"greek\">ἐὰν</span>, <span class=\"greek\">εἰ</span> e infinitivo. Ver também as formas abreviadas <span class=\"greek\">θ</span>. nas citações antigas, a construção <span class=\"greek\">τὶ</span> e o sujeito <span class=\"greek\">ὁ</span> <span class=\"greek\">θέλων</span>, «aquele que quer».</p></section><p class=\"entry-text\">Na sintaxe citada, <span class=\"greek\">τὶ</span> é acusativo de coisa desejada; o particípio genitivo <span class=\"greek\">θελόντων</span> figura entre as formas usadas para descrever agentes que querem realizar algo (cf. Diógenes Laércio 6, 34).</p></article>\n<article id=\"entry-thema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">τίθημι</span>; Cebes, Plutarco; inscrições, papiros, LXX; SibOr 2, 46, 49.) Originalmente «depósito de dinheiro»; nesta literatura, <strong>prêmio oferecido aos competidores</strong>, quando consiste em dinheiro e não em coroa (SIG 1063, 21, nota 4; OGI 339, 81s.; 566, 28). <span class=\"greek\">θ</span>. <span class=\"greek\">ἀφθαρσία</span>, «o prêmio é a incorruptibilidade», IPol 2:3 (Zahn, em sua edição, alterou desnecessariamente <span class=\"greek\">ἀφθαρσία</span>, leitura dos manuscritos, para genitivo). <span class=\"greek\">θέμα</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">καλόν</span>, «prêmio excepcionalmente excelente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:19</a>, conjectura. — DELG, s.v. <span class=\"greek\">τίθημι</span>.</p></section></article>\n<article id=\"entry-themelion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεμέλιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes seguintes; Méoris, p. 185, qualifica a forma neutra e o plural <span class=\"greek\">θεμέλια</span> como propriamente áticos, mas não coincide com os testemunhos literários; neutro em Aristóteles, Phys. Auscult. 2, 9, p. 200a, 4; Heráclito Estoico 38, p. 55, 20; Pausânias 8, 32, 1; Vécio Valente, índice; Pseudo-Luciano, Salt. 34; papiros [Mayser 289]; LXX [Thackeray 154].) <strong>Fundação, alicerce, base</strong>. Em nossa literatura aparece apenas no plural: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:26</a>; B 6:2 (Is 28:16); Hs 9, 5, 4; 9, 15, 4; 9, 21, 2, em sentido literal e no figurado dos indecisos descritos como plantas com folhas verdes e raízes secas. Em outras passagens o gênero não é determinável ou o termo pertence ao artigo seguinte, que reúne as ocorrências ambíguas. Contudo, o dativo <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεμελίοις</span>, Hs 9, 4, 3, não deve ser atribuído ao masculino, pois Hermas emprega o neutro nas demais ocorrências. — TW; DELG, s.v. <span class=\"greek\">θεμός</span> (cf. <span class=\"greek\">τίθημι</span>).</p></section></article>\n<article id=\"entry-themelios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεμέλιος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver artigos anterior e seguinte; Tucídides 1, 93, 2; Políbio 1, 40, 9; Luciano, Calum. 20; Mácon, Com. Fgm. 2 V. 2 K. [Ateneu 8, 346a]; Epicteto 2, 15, 8; SIG 888, 55, 70; LXX [Thackeray 154]; En 18:1; TestSol 8:12, <span class=\"greek\">τοὺς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>; JosAs 15:13, códice A [p. 62, 12 Bat.], <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεμελίων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀβύσσου</span>; Fílon, Cher. 101; Spec. Leg. 2, 110; Josefo, Bell. 5, 152; Ant. 5, 31; 11, 19; empréstimo ao vocabulário rabínico.) O masculino é certamente singular em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:11s</a>.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:19b</a>; 1Cl 33:3; Hs 9, 4, 2; 9, 14, 6; plural em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:14</a>, 19a.</p><p class=\"entry-text\">① <strong>Base que sustenta uma estrutura: fundamento</strong>.</p><p class=\"entry-text\">ⓐ De pedra que constitui um alicerce (Aristófanes, Aves 1137, <span class=\"greek\">θεμέλιοι</span> <span class=\"greek\">λίθοι</span>, aqui adjetivo), <span class=\"greek\">θεμελίους</span>, «pedras fundamentais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:14</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:19a</a>; <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:19b</a>.</p><p class=\"entry-text\">ⓑ Da base estrutural de um edifício (Diodoro Sículo 11, 63, 1, <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεμελίων</span>; Fílon, Exsecr. 120, <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεμελίων</span> <span class=\"greek\">ἄχρι</span> <span class=\"greek\">στέγους</span> <span class=\"greek\">οἰκίαν</span>; TestSol 8:12, <span class=\"greek\">ὀρύσσειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>): <span class=\"greek\">χωρὶς</span> <span class=\"greek\">θεμελίου</span>, «sem alicerce», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:49</a>. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">θεμέλιον</span>, «lançar fundamento» (cf. Hipérides 6, 14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:29</a>; com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, «sobre algo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:48</a>. Fundamentos da cidade celestial construída por Deus: <span class=\"greek\">τοὺς</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:10</a> (R. Knopf, Festschrift Heinrici, 1914, 215; L. Muntingh, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>–10 e os textos de Mari, Festschrift A. van Selms, 1971, 108–20).</p><p class=\"entry-text\">② <strong>Base para que algo aconteça ou venha a existir: fundamento</strong>, extensão figurada de ①.</p><p class=\"entry-text\">ⓐ Começos elementares de uma realidade, por exemplo, fundação de comunidade: <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀλλότριον</span> <span class=\"greek\">θ</span>., «sobre fundamento alheio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:20</a>; <span class=\"greek\">θεμέλιον</span> <span class=\"greek\">ἔθηκα</span>, «lancei o fundamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:10</a>; <span class=\"greek\">οἰκοδομεῖν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., «edificar sobre o fundamento», versículo 12. De ensinamentos elementares: <span class=\"greek\">θεμέλιον</span> <span class=\"greek\">καταβάλλεσθαι</span>, «lançar fundamento» (Dionísio de Halicarnasso 3, 69; uso literal em Josefo, Ant. 11, 93; 15, 391), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκοδομῆς</span>, «fundamento da construção», Hs 9, 4, 2; de Cristo, ver ②ⓑ.</p><p class=\"entry-text\">ⓑ <strong>Pré-requisito indispensável</strong>: a vontade divina é o fundamento da criação ordenada, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀσφαλῆ</span> … <span class=\"greek\">θ</span>., «sobre o fundamento seguro», 1Cl 33:3. Fundamento da igreja: Cristo, <span class=\"greek\">θ</span>. … <span class=\"greek\">ἄλλον</span> … <span class=\"greek\">θεῖναι</span>, «lançar outro fundamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:11</a> (A. Fridrichsen, TZ 2, 1946, 316s.); <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐγένετο</span>, «ele [Filho de Deus] tornou-se seu fundamento», Hs 9, 14, 6; apóstolos e profetas: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., «sobre o fundamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:20</a>; cf. <span class=\"greek\">ὁ</span> … <span class=\"greek\">στερεὸς</span> … <span class=\"greek\">θ</span>., «fundamento firme», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:19</a>.</p><p class=\"entry-text\">ⓒ O fundamento propicia estabilidade e, portanto, pode ser <strong>tesouro, reserva</strong> (Fílon, Sacr. Abel. 81, <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φαύλῳ</span> <span class=\"greek\">κακία</span>; Leg. All. 3, 113): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:19</a>, <span class=\"greek\">θεμέλιον</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span>, «algo excelente sobre que construir para o futuro». — DELG, s.v. <span class=\"greek\">θεμός</span>; Frisk, s.v. <span class=\"greek\">θέμεθλα</span>; M-M; TW.</p><p class=\"entry-text\">A forma substantiva <span class=\"greek\">θεμέλιος</span>, «alicerce», reaparece nos testemunhos como base material e espiritual.</p></section></article>\n<article id=\"entry-themelioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεμελιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">θεμέλιος</span>; Xenofonte, Cyr. 7, 5, 11; SIG 1104, 15; inscrição da sinagoga de Jerusalém, SEG VIII 170, 9 [anterior a 70 d.C.]; LXX, En, TestSol, JosAs 12:3 [códice A, cap. 19, p. 69, 18 Bat.]; Fílon, Op. M. 102.) Futuro <span class=\"greek\">θεμελιώσω</span>; primeiro aoristo <span class=\"greek\">ἐθεμελίωσα</span>; passiva: primeiro aoristo terceira pessoa singular <span class=\"greek\">ἐθεμελιώθη</span> na LXX; perfeito <span class=\"greek\">τεθεμελίωμαι</span>; mais-que-perfeito terceira pessoa singular <span class=\"greek\">τεθεμελίωτο</span> (a respeito da ausência de aumento, B-D-F §66, 1; W-S §12, 4; Mlt-H. 190).</p><p class=\"entry-text\">① <strong>Prover fundamento para estrutura material, lançar alicerce, fundar</strong>, com objeto <span class=\"greek\">τὶ</span>: <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, «a terra» (Jó 38:4; Pv 3:19; En 18:12; 21:2; JosAs 12:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:10</a>; Hm 12, 4, 1, variante (Sl 101:26). <span class=\"greek\">θεμελιώσας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὑδάτων</span>, «que fundou a terra sobre as águas», Hv 1, 3, 4 (Sl 23:2). Também <span class=\"greek\">ἐπί</span> com acusativo: <span class=\"greek\">τεθεμελίωτο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πέτραν</span>, «estava fundada sobre a rocha», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:48</a>, variante.</p><p class=\"entry-text\">② <strong>Prover base segura para a vida interior e seus recursos: estabelecer, fortalecer</strong>, extensão figurada de ① (Diodoro Sículo 11, 68, 7, <span class=\"greek\">βασιλεία</span> <span class=\"greek\">καλῶς</span> <span class=\"greek\">θεμελιωθεῖσα</span>; 15, 1, 3).</p><p class=\"entry-text\">ⓐ De crentes estabelecidos por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5:10</a>; ou a quem ele concede lugar seguro, Hv 1, 3, 2. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:23</a>; Hv 3, 13, 4; 4, 1, 4.</p><p class=\"entry-text\">ⓑ Das revelações recebidas por Hermas: <span class=\"greek\">πάντα</span> <span class=\"greek\">τεθεμελιωμένα</span> <span class=\"greek\">ἐστίν</span>, «todas estão bem fundamentadas», Hv 3, 4, 3. Da igreja figurada como torre: <span class=\"greek\">τεθεμελίωται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντοκράτορος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξου</span> <span class=\"greek\">ὀνόματος</span>, «foi estabelecida pela palavra do nome onipotente e glorioso [de Deus]», Hv 3, 3, 5. — DELG, s.v. <span class=\"greek\">θεμός</span>; M-M; TW.</p></section></article>\n<article id=\"entry-themitos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεμιτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">θέμις</span>, «lei estabelecida pelo costume»; Hinos homéricos, Heródoto e outros; inscrições, papiros; Josefo, Bell. 6, 432.) <strong>Aquilo que é correto ou apropriado</strong>, não necessariamente por lei codificada, mas por norma costumeira e consciência do transcendente: <strong>permitido, lícito, justo</strong>. <span class=\"greek\">θεμιτόν</span> <span class=\"greek\">ἐστιν</span>, «é correto», com infinitivo (Sexto Empírico, Adv. Gramm. 81; SIG 965, 16s.), 1Cl 63:1. Mais frequentemente com negação (Heródoto 5, 72 e outros; Élio Aristides 45, p. 25 D.; Tb 2:13 BA; Fílon, Op. M. 17, <span class=\"greek\">οὐ</span> <span class=\"greek\">θ</span>.; Josefo, Ant. 14, 72): <span class=\"greek\">οὐ</span> <span class=\"greek\">θ</span>., «não é permitido» (sem cópula, Hipérides 6, 27; Justino, D. 134, 3; Atanásio, R. 77, 29), Dg 6:10. — H. Vos, <em><span class=\"greek\">ΘΕΜΙΣ</span></em>, 1956; LfgrE coluna 991 (bibliografia), s.v. <span class=\"greek\">θέμις</span>; DDD 1613s.; DELG, s.v. <span class=\"greek\">θέμις</span>.</p></section></article>\n<article id=\"entry-theodidaktos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοδίδακτος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Prolegomenon Syll., p. 91, 14 [João Doxópatres, retor do século XI, em comentário aos Progymnasmata de Aftônio], <span class=\"greek\">θεοδίδακτος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥητορική</span>; não é, porém, termo exclusivamente retórico, C. Classen, WienerStud 107/108, 1994/95, 332s.; também escritores eclesiásticos, Lampe; ver <span class=\"greek\">διδακτός</span> 1; Máximo de Tiro 26, 1c, <span class=\"greek\">Ἀπόλλωνος</span> <span class=\"greek\">διδάγματα</span>; Pseudo-Calístenes 1, 13, 5, <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">διδασκόμενος</span>; Damáscio, Princ. 111, p. 229 R., <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span> <span class=\"greek\">διδαχθέντες</span>; Teófilo de Antioquia 2, 9 [p. 120, 3], junto de <span class=\"greek\">ὅσιος</span> e <span class=\"greek\">δίκαιος</span>.) <strong>Ensinado, instruído por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:9</a> (J. Kloppenberg, NTS 39, 1939, 281–89, alusão aos Dióscuros como paradigmas de <span class=\"greek\">φιλαδελφία</span>); B 21:6. — DELG, s.v. <span class=\"greek\">διδάσκω</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-theodromos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοδρόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">θεός</span>, <span class=\"greek\">δρόμος</span>; provavelmente neologismo de Inácio, talvez fundamentado em passagens como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:24</a>–26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:7</a>.) <strong>Corredor de Deus</strong>, IPhld 2:2; IPol 7:2. — Cf. DELG, s.v. <span class=\"greek\">δραμεῖν</span>.</p></section></article>\n<article id=\"entry-theologos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεολόγος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">θεός</span>, <span class=\"greek\">λόγος</span>; Aristóteles e posteriores; Diodoro Sículo 5, 80, 4; Filodemo; Plutarco, Mor. 417f; Sexto Empírico, Math. 2, 31; Diógenes Laércio 1, 119; Porfírio, Abst. 2, 36–43, <span class=\"greek\">ἅ</span> <span class=\"greek\">τε</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεολόγος</span> [Orfeu]; inscrições especialmente no culto imperial da Ásia Menor [OGI 513, nota 4, século III d.C.]; PGM 13, 933, <span class=\"greek\">ὡς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεολόγος</span> <span class=\"greek\">Ὀρφεὺς</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παραστιχίδος</span>; Apolônio Paradoxógrafo 4, de Ábaris; Fílon, Praem. 53, de Moisés.) <strong>Aquele que fala de Deus ou de assuntos divinos, arauto de Deus</strong>; cognome eclesiástico dado a João, posteriormente a outros, Apocalipse, inscrição, variante de leitura. — Deissmann, NB 58s. (BS 231s.), LO 297 (LAE 353, nota 1); Reitzenstein, <em>Hist. Mon.</em>, 135ss.; F. Kattenbusch, «D. Entstehung e. christl. Theologie», ZTK n.s. 11, 1930, 161–205; M-M; Sv.</p><p class=\"entry-text\">A história terminológica dos vocábulos <span class=\"greek\">θεολογία</span>, «teologia», e <span class=\"greek\">θεολογεῖν</span>, «discorrer acerca da divindade», é tratada por Kattenbusch juntamente com <span class=\"greek\">θεολόγος</span>.</p></section></article>\n<article id=\"entry-theomakaristos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεομακάριστος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Abençoado por Deus</strong>: de Policarpo, superlativo <span class=\"greek\">θεομακαριστότατος</span>, IPol 7:2. Também da paixão de Cristo, <span class=\"greek\">θ</span>. … <span class=\"greek\">πάθους</span>, ISm 1:2. Ver verbete seguinte. — DELG, s.v. <span class=\"greek\">μάκαρ</span>.</p></section></article>\n<article id=\"entry-theomakarites-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεομακαρίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino empregado como adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<em>Hapax legomenon</em>; <span class=\"greek\">μακαρίτης</span>, «aquele que foi abençoado», isto é, «falecido, recentemente morto» [Ésquilo e outros].) Usado como adjetivo (assim <span class=\"greek\">μακαρίτης</span> em Aristófanes, Pl. 555), <strong>divinamente abençoado</strong>, da paixão de Cristo, ISm 1:2, variante de leitura (ver <span class=\"greek\">θεομακάριστος</span>). — DELG, s.v. <span class=\"greek\">μάκαρ</span>.</p></section></article>\n<article id=\"entry-theomacheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεομαχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver verbete seguinte; Eurípides, Iph. A. 1409; Xenofonte, Oec. 16, 3; Menandro, Fgm. 162 Kö. = 187, p. 54 Kock, <span class=\"greek\">μὴ</span> <span class=\"greek\">θεομάχει</span>; Manetão, 609 Fgm. 10, p. 95, 7 Jac. [Josefo, C. Ap. 1, 246]; Josefo, C. Ap. 1, 263; Diodoro Sículo 14, 69, 2; Epicteto 3, 24, 21, 24; 4, 1, 101; M. Adinolfi, <em>Atti del IV Simposio di Tarso su S. Paolo Apostolo</em>, ed. L. Padovese, 1996, 63s.; Filóstrato, Vi. Apoll. 4, 44; 2Mc 7:19.) <strong>Combater Deus, opor-se a Deus e às suas obras</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:9</a>, variante de leitura. — W. Nestle, Philologus 59, 1900, 48–50; O. Weinreich, <em>Gebet und Wunder</em>, 1929, 172s.; Pauly-W., Suppl. IV, 1924, 290s.; DELG, s.v. <span class=\"greek\">μάχομαι</span>; M-M.</p></section></article>\n<article id=\"entry-theomachos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεομάχος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver verbete anterior; Címno, geógrafo [século II a.C.], 637 C. Müller; Heráclito Estoico 1, p. 1, 7; Luciano, Jupp. Tr. 45; Vécio Valente 331, 12; Símaco, Jó 26:5; Pv 9:18; 21:16; cf. Josefo, Ant. 14, 310; Taciano 13, 3.) <strong>Que combate contra Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:39</a>. — A. Vögeli, «Lk and Eur.», TZ 9, 1953, 415–38; DELG, s.v. <span class=\"greek\">μάχομαι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-theonoe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεονόη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Roscher V 631s.; papiros desde o século VI d.C.) <strong>Teónoe</strong>, uma cristã de Corinto: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀπεκαλύφθη</span> <span class=\"greek\">Θεονόῃ</span>, «conforme foi revelado a Teónoe», AcPlCor 1:8.</p></section></article>\n<article id=\"entry-theopneustos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεόπνευστος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">θεός</span> e <span class=\"greek\">πνέω</span>; Pseudo-Focílides 129, <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοπνεύστου</span> <span class=\"greek\">σοφίης</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἄριστος</span> [Horst 201s.]; Plutarco, Mor. 904f; Vécio Valente 330, 19; Pseudo-Calístenes 1, 25, 2; SibOr 5, 308, 406; TestAbr A 20, p. 103, 22 [Stone p. 54], <span class=\"greek\">μυρίσμασι</span> <span class=\"greek\">θ</span>.; para o conceito, cf. <span class=\"greek\">θεία</span> <span class=\"greek\">ἐπίπνοια</span>, SIG 695, 12; sobre esses testemunhos, B. Warfield, <em>Revelation and Inspiration</em>, 1927, 229–59; New Docs 3, 30; também 1, 15.) <strong>Inspirado por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:16</a> (M. Austin, ET 93, 1981, 75–79, interpretação por «expiração»). — DELG, s.v. <span class=\"greek\">πνέω</span>; M-M; TW; Spicq.</p></section></article>\n"};
